interface.definition:
a!localVariables(
  local!approverGroupNames: #"SYSTEM_SYSRULES_forEach"(
    items: ri!DPPApproversList,
    expression: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3374322"(
      selectedGroup: togroup(fv!item)
    )
  ),
  local!approverGroups:#"SYSTEM_SYSRULES_forEach"(
    items: ri!DPPApproversList,
    expression: togroup(fv!item)
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      showDividers: true,
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_dropdownField_v1"(
              label:"Select Additional Approver from DPP Leadership",
              placeholder: "Select Approver",
              choiceLabels: local!approverGroupNames,
              choiceValues: local!approverGroups,
              value: ri!selectedGroup,
              saveInto: ri!selectedGroup,
              disabled: or(#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!isComplete),#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!isSendToNMP))
            )    
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_checkboxField"(
              label:"Send to DPP PIC for Approval",
              choiceLabels: "",
              choiceValues: true,
              value: ri!isSendToNMP,
              saveInto: {
                ri!isSendToNMP,
                a!save(
                  ri!nmpGroup,
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177089"
                ),
                if(
                  #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!isSendToNMP),
                  a!save(
                    ri!nmpGroup,
                    null
                  ),
                  null
                )
              },
              disabled: or(#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!selectedGroup),#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!isComplete))
            )
          },
          showWhen: ri!askTypeId = #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3161580"
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_checkboxField"(
              label:"Mark as Complete",
              choiceLabels: "Complete",
              choiceValues: true,
              value: ri!isComplete,
              saveInto: ri!isComplete,
              disabled: or(#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!selectedGroup),#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!isSendToNMP))
            )
          }
        )
      }
    )
  },
  showWhen: ri!showWhen
  )
)

a:ruleInputTestConfigs.a:value:
#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
  reject(
    fn!isnull,
    #"SYSTEM_SYSRULES_forEach"(
      items: if(true=true,
      remove(#"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3240923",10),
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3240923"
      ),
      expression: if(
        tointeger(a!groupMembers(fv!item).totalCount) <> 0,
        fv!item,
        null
      )
    )
  ))
